using System.Text.Json;
using KnowledgeNetworkDemo.Api.Infrastructure;
using KnowledgeNetworkDemo.Api.Models;
using VDS.RDF;
using VDS.RDF.Query;

namespace KnowledgeNetworkDemo.Api.Repositories;

/// <summary>
/// SPARQL-backed implementation of <see cref="IGraphRepository"/>. All
/// query text lives in <c>backend/Sparql/*.rq</c> as embedded resources;
/// this class only folds result rows into DTOs.
/// <para>
/// Graph scope is the domain layer (<c>knd:</c>). Type and style scopes
/// are the meta (<c>kn:</c>) and meta-instance (<c>knm:</c>) layers —
/// i.e. the self-description the reflexive model makes available.
/// </para>
/// <para>
/// Property values collapse to the last binding per (subject, predicate);
/// datatypes round-trip to <see cref="JsonElement"/> via
/// <see cref="ToJsonElement"/>, which preserves xsd:boolean / integer /
/// double distinctions on the wire.
/// </para>
/// </summary>
public sealed class SparqlGraphRepository : IGraphRepository
{
    private readonly IRdfQueryClient _client;

    private const string Rdf  = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
    private const string Rdfs = "http://www.w3.org/2000/01/rdf-schema#";
    private const string Kn   = "http://knowledgenetwork.local/meta#";

    // Predicates already represented as first-class DTO fields or projected
    // as edges in the meta-view; they must not leak into the node property
    // bag as duplicates.
    private static readonly HashSet<string> ExcludedNodePredicates = new(StringComparer.Ordinal)
    {
        $"{Rdf}type",
        $"{Rdfs}label",
        $"{Kn}type_of",
        $"{Kn}source",
        $"{Kn}target",
        $"{Kn}domain",
        $"{Kn}range",
        $"{Kn}subtype_of",
    };

    // Predicates already represented as first-class fields on VisualStyle;
    // everything else becomes a properties-bag entry.
    private static readonly HashSet<string> ExcludedStylePredicates = new(StringComparer.Ordinal)
    {
        $"{Rdf}type",
        $"{Kn}applies_to",
        $"{Kn}subtype_of",
        $"{Kn}filter_property",
        $"{Kn}filter_value",
    };

    public SparqlGraphRepository(IRdfQueryClient client)
    {
        _client = client;
    }

    public async Task<GraphEnvelope> GetGraphAsync(string view = "domain", CancellationToken ct = default)
    {
        var isMeta = string.Equals(view, "meta", StringComparison.OrdinalIgnoreCase);
        var nodesQuery = isMeta ? SparqlQueries.NodesMeta : SparqlQueries.Nodes;
        var edgesQuery = isMeta ? SparqlQueries.EdgesMeta : SparqlQueries.Edges;

        var nodes = await LoadNodesAsync(nodesQuery, ct).ConfigureAwait(false);
        var edges = await LoadEdgesAsync(edgesQuery, ct).ConfigureAwait(false);
        return new GraphEnvelope
        {
            Nodes = nodes,
            Edges = edges,
        };
    }

    public async Task<TypeCatalog> GetTypesAsync(CancellationToken ct = default)
