4	#
5	# Every user-authored NodeType and EdgeType, plus the four L1 primitives
6	# (kn:Node, kn:Edge, kn:NodeType, kn:EdgeType), returned in the same
7	# uniform node shape as domain-view nodes. The L1 primitives self-type
8	# via kn:type_of (not rdf:type) to avoid rdf-type loops, so we include
9	# them explicitly rather than relying on `a`.
10	#
11	# typeUri resolves to kn:NodeType or kn:EdgeType — the apex classes the
12	# meta-model already carries visual styles for (or will, once meta styles
13	# are authored). The frontend renders using the same style-cascade path.
14	
15	SELECT ?id ?type ?label ?prop ?value WHERE {
16	  {
17	    ?id a kn:NodeType .
18	    BIND(kn:NodeType AS ?type)
19	  } UNION {
20	    ?id a kn:EdgeType .
21	    BIND(kn:EdgeType AS ?type)
22	  } UNION {
23	    VALUES ?id { kn:Node kn:Edge kn:NodeType kn:EdgeType }
24	    BIND(kn:NodeType AS ?type)
25	  }
26	  OPTIONAL { ?id rdfs:label ?label }
27	  OPTIONAL { ?id ?prop ?value }
