__PREFIXES__

# Meta-view nodes (Stage 5, Claim 7).
#
# Every user-authored NodeType and EdgeType, plus the four L1 primitives
# (kn:Node, kn:Edge, kn:NodeType, kn:EdgeType), returned in the same
# uniform node shape as domain-view nodes. The L1 primitives self-type
# via kn:type_of (not rdf:type) to avoid rdf-type loops, so we include
# them explicitly rather than relying on `a`.
#
# typeUri resolves to kn:NodeType or kn:EdgeType — the apex classes the
# meta-model already carries visual styles for (or will, once meta styles
# are authored). The frontend renders using the same style-cascade path.

SELECT ?id ?type ?label ?prop ?value WHERE {
  {
    ?id a kn:NodeType .
    BIND(kn:NodeType AS ?type)
  } UNION {
    ?id a kn:EdgeType .
    BIND(kn:EdgeType AS ?type)
  } UNION {
    VALUES ?id { kn:Node kn:Edge kn:NodeType kn:EdgeType }
    BIND(kn:NodeType AS ?type)
  }
  OPTIONAL { ?id rdfs:label ?label }
  OPTIONAL { ?id ?prop ?value }
}

