2	# meta.ttl — Level 1 primitives of the KnowledgeNetworkDemo reflexive meta-model.
3	#
4	# Source spec: KnowledgeNetworkDemo-design/META_MODEL_DESIGN.md (Accepted 2026-04-21)
5	# Stage 3a output, 2026-04-21.
6	#
7	# Contents
8	#   1. Prefixes
9	#   2. Primitive node types (kn:Node, kn:NodeType, kn:EdgeType, kn:Edge)
10	#   3. Primitive edge types (kn:type_of, kn:subtype_of, kn:source, kn:target)
11	#   4. The fixed point (self-referential typing)
12	#   5. OWL equivalence declarations (the bridge to reasoning)
13	#   6. Visual-style primitives (kn:VisualStyle, kn:NodeVisualStyle, kn:EdgeVisualStyle)
14	#
15	# This file loads first. It is self-referential on purpose:
16	# `kn:NodeType kn:type_of kn:NodeType` is the pin that terminates the regress.
17	#
18	
19	@prefix kn:    <http://knowledgenetwork.local/meta#> .
20	@prefix rdf:   <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
21	@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
22	@prefix owl:   <http://www.w3.org/2002/07/owl#> .
