24	
25	#
26	# ---------------------------------------------------------------------------
27	# 2. Primitive node types
28	# ---------------------------------------------------------------------------
29	#
30	
31	kn:Node
32	    kn:type_of          kn:NodeType ;
33	    rdfs:label          "Node" ;
34	    kn:description      "The root of the type hierarchy. Everything in the system is a kn:Node." ;
35	    owl:equivalentClass owl:Thing .
36	
37	kn:NodeType
