40	    rdfs:label          "NodeType" ;
41	    kn:description      "A class of nodes. Instances of kn:NodeType are user-authored categories such as knm:Concept, knm:Course." ;
42	    owl:equivalentClass owl:Class .
43	
44	kn:EdgeType
