46	    kn:subtype_of       kn:Node ;
47	    rdfs:label          "EdgeType" ;
48	    kn:description      "A class of edges. Instances of kn:EdgeType are user-authored relationship kinds such as knm:prerequisite_of." ;
49	    owl:equivalentClass owl:ObjectProperty .
50	
51	kn:Edge
52	    kn:type_of          kn:NodeType ;
53	    kn:subtype_of       kn:Node ;
54	    rdfs:label          "Edge" ;
55	    kn:description      "A reified edge. An instance of kn:Edge is a single edge in the graph, represented as a node so it can carry properties and participate in other edges." .
56	
