64	    kn:type_of             kn:EdgeType ;
65	    rdfs:label             "type_of" ;
66	    kn:description         "Links any node to its type. Ubiquitous reflexive edge." ;
67	    kn:edge_category       "system" ;
68	    owl:equivalentProperty rdf:type .
69	
70	kn:subtype_of
71	    kn:type_of             kn:EdgeType ;
72	    rdfs:label             "subtype_of" ;
73	    kn:description         "Links a type to a more general type. Overloaded: subClassOf between NodeTypes, subPropertyOf between EdgeTypes." ;
74	    kn:edge_category       "system" ;
