#
# meta.ttl — Level 1 primitives of the KnowledgeNetworkDemo reflexive meta-model.
#
# Source spec: KnowledgeNetworkDemo-design/META_MODEL_DESIGN.md (Accepted 2026-04-21)
# Stage 3a output, 2026-04-21.
#
# Contents
#   1. Prefixes
#   2. Primitive node types (kn:Node, kn:NodeType, kn:EdgeType, kn:Edge)
#   3. Primitive edge types (kn:type_of, kn:subtype_of, kn:source, kn:target)
#   4. The fixed point (self-referential typing)
#   5. OWL equivalence declarations (the bridge to reasoning)
#   6. Visual-style primitives (kn:VisualStyle, kn:NodeVisualStyle, kn:EdgeVisualStyle)
#
# This file loads first. It is self-referential on purpose:
# `kn:NodeType kn:type_of kn:NodeType` is the pin that terminates the regress.
#

@prefix kn:    <http://knowledgenetwork.local/meta#> .
@prefix rdf:   <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:   <http://www.w3.org/2002/07/owl#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .

#
# ---------------------------------------------------------------------------
# 2. Primitive node types
# ---------------------------------------------------------------------------
#

kn:Node
    kn:type_of          kn:NodeType ;
    rdfs:label          "Node" ;
    kn:description      "The root of the type hierarchy. Everything in the system is a kn:Node." ;
    owl:equivalentClass owl:Thing .

kn:NodeType
    kn:type_of          kn:NodeType ;          # the fixed point
    kn:subtype_of       kn:Node ;
    rdfs:label          "NodeType" ;
    kn:description      "A class of nodes. Instances of kn:NodeType are user-authored categories such as knm:Concept, knm:Course." ;
    owl:equivalentClass owl:Class .

kn:EdgeType
    kn:type_of          kn:NodeType ;
    kn:subtype_of       kn:Node ;
    rdfs:label          "EdgeType" ;
    kn:description      "A class of edges. Instances of kn:EdgeType are user-authored relationship kinds such as knm:prerequisite_of." ;
    owl:equivalentClass owl:ObjectProperty .

kn:Edge
    kn:type_of          kn:NodeType ;
    kn:subtype_of       kn:Node ;
    rdfs:label          "Edge" ;
    kn:description      "A reified edge. An instance of kn:Edge is a single edge in the graph, represented as a node so it can carry properties and participate in other edges." .

#
# ---------------------------------------------------------------------------
# 3. Primitive edge types
# ---------------------------------------------------------------------------
#

kn:type_of
    kn:type_of             kn:EdgeType ;
    rdfs:label             "type_of" ;
    kn:description         "Links any node to its type. Ubiquitous reflexive edge." ;
    kn:edge_category       "system" ;
    owl:equivalentProperty rdf:type .

kn:subtype_of
    kn:type_of             kn:EdgeType ;
    rdfs:label             "subtype_of" ;
    kn:description         "Links a type to a more general type. Overloaded: subClassOf between NodeTypes, subPropertyOf between EdgeTypes." ;
    kn:edge_category       "system" ;
    a                      owl:TransitiveProperty ;
    owl:equivalentProperty rdfs:subClassOf .
    # Note: equivalence to rdfs:subPropertyOf is enforced per-context by the
    # backend when both endpoints are kn:EdgeType instances.

kn:source
    kn:type_of             kn:EdgeType ;
    rdfs:label             "source" ;
    kn:description         "Tail endpoint of a reified kn:Edge." ;
    kn:edge_category       "system" .

kn:target
    kn:type_of             kn:EdgeType ;
    rdfs:label             "target" ;
    kn:description         "Head endpoint of a reified kn:Edge." ;
    kn:edge_category       "system" .

#
# ---------------------------------------------------------------------------
# 4. The projection rule is applied at query time via SPARQL CONSTRUCT
#    (backend responsibility, not expressed in this file).
#
#    CONSTRUCT { ?s ?p ?o }
#    WHERE {
#      ?edge kn:type_of ?p ;
#            kn:source  ?s ;
#            kn:target  ?o .
#      ?p a kn:EdgeType .
#    }
# ---------------------------------------------------------------------------
#

#
# ---------------------------------------------------------------------------
# 5. Visual-style primitives
# ---------------------------------------------------------------------------
#

kn:VisualStyle
    kn:type_of          kn:NodeType ;
    kn:subtype_of       kn:Node ;
    rdfs:label          "VisualStyle" ;
    kn:description      "Abstract root for all visual-style nodes. Not instantiated directly." .

kn:NodeVisualStyle
    kn:type_of          kn:NodeType ;
    kn:subtype_of       kn:VisualStyle ;
    rdfs:label          "NodeVisualStyle" ;
    kn:description      "Visual style specification applied to kn:NodeType instances. Carries color, icon, size, border_style, label_position." .

kn:EdgeVisualStyle
    kn:type_of          kn:NodeType ;
    kn:subtype_of       kn:VisualStyle ;
    rdfs:label          "EdgeVisualStyle" ;
    kn:description      "Visual style specification applied to kn:EdgeType instances. Carries color, line_style, arrow_head, width, label_position." .

#
# ---------------------------------------------------------------------------
# 6. Meta-property declarations
#    These are the properties the above primitives reference. Declared here
#    so that meta-instance files (meta-instances.ttl, domain.ttl) can use
#    them without redeclaration.
# ---------------------------------------------------------------------------
#

kn:description
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "description" ;
    kn:description      "Optional longer text describing a node." .

kn:visual_style
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "visual_style" ;
    kn:description      "Links a NodeType or EdgeType to its visual style node." .

kn:edge_category
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "edge_category" ;
    kn:description      "Classification of an edge type: 'domain', 'system', 'derived', 'audit'." .

kn:owl_semantics
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "owl_semantics" ;
    kn:description      "OWL characteristic declared for an edge type: Transitive, Symmetric, Functional, InverseFunctional." .

kn:inverse_edge_type
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "inverse_edge_type" ;
    kn:description      "Links an EdgeType to its inverse EdgeType (e.g., demonstrates / is_demonstrated_by)." .

kn:default_properties
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "default_properties" ;
    kn:description      "List of property names instances of a NodeType are expected to carry." .

kn:derived
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "derived" ;
    kn:description      "Boolean flag marking an edge type as derived (produced by inference, not user-authored)." .

# Visual-style properties
kn:color           kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "color" .
kn:icon            kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "icon" .
kn:size            kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "size" .
kn:border_style    kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "border_style" .
kn:border_color    kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "border_color" .
kn:shape           kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "shape" .
kn:badge           kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "badge" .
kn:opacity         kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "opacity" .
kn:hidden_by_default kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "hidden_by_default" .
kn:label_position  kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "label_position" .
kn:line_style      kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "line_style" .
kn:arrow_head      kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "arrow_head" .
kn:width           kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "width" .

# Filter / scope properties on visual styles
kn:applies_to            kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "applies_to" ;
                         kn:description "Links a visual style to the node/edge type it styles." .
kn:applies_to_category   kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "applies_to_category" ;
                         kn:description "Scopes an edge style to all edge types with a given kn:edge_category." .
kn:applies_to_owl        kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "applies_to_owl" ;
                         kn:description "Scopes an edge style to all edge types with a given OWL characteristic." .
kn:applies_to_derived    kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "applies_to_derived" ;
                         kn:description "Scopes an edge style to all derived edge types." .
kn:filter_property       kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "filter_property" ;
                         kn:description "Property descriptor used to select a style variant for a node type." .
kn:filter_value          kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "filter_value" ;
                         kn:description "Value the filter property must match for the variant style to apply." .

# Domain / range / category metadata on types
kn:category        kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "category" ;
                   kn:description "Classifies a kn:NodeType as 'knowledge', 'organizational', or 'supporting'." .
kn:domain          kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "domain" ;
                   kn:description "Allowed source node type for instances of this edge type." .
kn:range           kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "range" ;
                   kn:description "Allowed target node type for instances of this edge type." .

# Property-descriptor machinery
kn:data_type       kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "data_type" ;
                   kn:description "XSD datatype of a property descriptor's value." .
kn:allowed_values  kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "allowed_values" ;
                   kn:description "Closed enumeration of values the property may take (validated outside OWL)." .

# Lifecycle / sys_contains defaults
kn:default_on_delete kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "default_on_delete" ;
                     kn:description "Default cascade behavior for instances of a system edge type." .
kn:default_exclusive kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "default_exclusive" ;
                     kn:description "Default exclusivity flag for instances of a system edge type." .
kn:user_editable     kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "user_editable" ;
                     kn:description "Whether end users may edit instances of this edge type through the UI." .
kn:on_delete         kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "on_delete" .
kn:exclusive         kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "exclusive" .
kn:auto_created      kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "auto_created" .

# Domain-node metadata used by knd:* instances
kn:document_id       kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "document_id" ;
                     kn:description "Stable public identifier for a domain node." .
kn:has_artifact      kn:type_of kn:EdgeType ; kn:edge_category "system" ; rdfs:label "has_artifact" ;
                     kn:description "Links a domain node to an attached knm:Artifact." .

