    rdfs:label          "edge_category" ;
    rdfs:comment        "Classification of an edge type: 'system', 'domain', or 'derived'. Distinguishes engine-internal containment from user-authored relations. (See ADR-002.)" .

kn:contains
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "contains" ;
    rdfs:comment        "Structural parent-child edge type. Used by the meta-visualization and by node-as-document binding. (See ADR-006.)" .

kn:body_ref
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "body_ref" ;
    rdfs:comment        "Substrate-to-doc-store binding for node-as-document. Object is an opaque URN the doc store resolves. (See ADR-006.)" .

#
# ---------------------------------------------------------------------------
# 5. Inference-protocol vocabulary (3)
#    Read by engine code to drive the Jena OWL 2 RL reasoner pass and the
#    derived-edge SPARQL CONSTRUCT step.
# ---------------------------------------------------------------------------
#

kn:owl_semantics
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "owl_semantics" ;
    rdfs:comment        "OWL characteristic declared for an edge type: Transitive, Symmetric, Functional, InverseFunctional. Read by the inference engine." .

kn:derived
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "derived" ;
    rdfs:comment        "Boolean flag marking an edge type as derived (produced by inference, not user-authored). Read by clear-and-recompute pass and validation exclusions." .

kn:inverse_edge_type
    kn:type_of          kn:EdgeType ;
    kn:edge_category    "system" ;
    rdfs:label          "inverse_edge_type" ;
    rdfs:comment        "Links an EdgeType to its inverse EdgeType (e.g., demonstrates / is_demonstrated_by). Read by the inference engine to generate inverse-direction edges." .

