    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Principle ;
    kn:color             "#EDE9FE" ;           # violet-100
    kn:border_color      "#A78BFA" .

knm:ExampleStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Example ;
    kn:color             "#D1FAE5" ;           # emerald-100
    kn:border_color      "#34D399" ;
    kn:badge             "eg" .

knm:AssessmentTestStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Assessment ;
    kn:filter_property   knm:format ;
    kn:filter_value      "test" ;
    kn:color             "#FEE2E2" ;
    kn:border_color      "#F87171" ;
    kn:badge             "✓" .

knm:AssessmentQuizStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Assessment ;
    kn:filter_property   knm:format ;
    kn:filter_value      "quiz" ;
    kn:color             "#FFEDD5" ;
    kn:border_color      "#FB923C" ;
    kn:badge             "?" .

knm:AssessmentExerciseStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Assessment ;
    kn:filter_property   knm:format ;
    kn:filter_value      "exercise" ;
    kn:color             "#FEF3C7" ;
    kn:border_color      "#FBBF24" ;
    kn:badge             "ex" .

knm:ReferenceStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Reference ;
    kn:color             "#F1F5F9" ;
    kn:border_color      "#94A3B8" ;
    kn:badge             "📄" .

knm:AnalogyStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Analogy ;
    kn:color             "#FCE7F3" ;
    kn:border_color      "#F472B6" ;
    kn:badge             "≈" .

knm:ProgramStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Program ;
    kn:color             "#E0E7FF" ;
    kn:border_color      "#818CF8" ;
    kn:badge             "🎓" ;
    kn:size              "large" .

knm:CourseStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
    kn:applies_to        knm:Course ;
    kn:color             "#CFFAFE" ;
    kn:border_color      "#22D3EE" ;
    kn:badge             "📘" .

knm:ProfessorStyle
    a                    kn:NodeVisualStyle ;
    kn:subtype_of        knm:DefaultNodeStyle ;
