```

### Edge styles

```turtle
knm:DomainEdgeStyle
    a                    kn:EdgeVisualStyle ;
    kn:subtype_of        knm:DefaultEdgeStyle ;
    kn:applies_to_category "domain" ;
    kn:color             "#475569" ;
    kn:line_style        "solid" ;
    kn:width             1.5 .

knm:SymmetricEdgeStyle
    a                    kn:EdgeVisualStyle ;
    kn:subtype_of        knm:DomainEdgeStyle ;
    kn:applies_to_owl    owl:SymmetricProperty ;
    kn:arrow_head        "double" .

knm:InferredEdgeStyle
    a                    kn:EdgeVisualStyle ;
    kn:subtype_of        knm:DomainEdgeStyle ;
    kn:applies_to_derived true ;
    kn:line_style        "dashed" ;
    kn:color             "#A855F7" .

knm:SystemEdgeStyle
    a                    kn:EdgeVisualStyle ;
    kn:subtype_of        knm:DefaultEdgeStyle ;
    kn:applies_to_category "system" ;
